package main

import (
	"encoding/json"
	"fmt"
	"io"
	"math"
	"os"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

func main() {
	var (
		noConvert bool
		escapeHTML bool
		indent bool
		parseKeys bool
		showHelp bool
		showVersion bool
	)

	var formatChars string
	args := os.Args[1:]
	var filteredArgs []string

	for _, arg := range args {
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			for i := 1; i < len(arg); i++ {
				c := arg[i]
				switch c {
				case 'n': noConvert = true
				case 'e': escapeHTML = true
				case 'i': indent = true
				case 'k': parseKeys = true
				case 'h': showHelp = true
				case 'v': showVersion = true
				case 'y', 't', 'j', 'c', 'r':
					formatChars += string(c)
				default:
					// ignore or handle error?
				}
			}
		} else {
			filteredArgs = append(filteredArgs, arg)
		}
	}

	if showHelp {
		printHelp()
		return
	}
	if showVersion {
		fmt.Println("v0.0.0")
		return
	}

	inputFormat, outputFormat := "y", "j" // default

	var formats []string
	for _, c := range formatChars {
		if c == 'r' {
			formats = append(formats, "j", "y")
		} else {
			formats = append(formats, string(c))
		}
	}

	if len(formats) == 1 {
		inputFormat = formats[0]
		outputFormat = "j"
	} else if len(formats) >= 2 {
		inputFormat = formats[len(formats)-2]
		outputFormat = formats[len(formats)-1]
	}

	inputData, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
		os.Exit(1)
	}

	var data interface{}
	// Use yaml.v3 for everything by default for order preservation
	// We'll need to handle TOML and HCL separately if needed.

    // For now, let's just implement YAML and JSON.
    // ...
}

func printHelp() {
	fmt.Println(`Usage: yj [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version`)
}
EOF
"}

