{"command":"cat <<'EOF' > main.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"os"
	"reflect"
	"strconv"
	"strings"

	"github.com/BurntSushi/toml"
	"github.com/hashicorp/hcl"
	"gopkg.in/yaml.v3"
)

func main() {
	var noConvert, escapeHTML, indent, parseKeys, showHelp, showVersion bool
	var formatChars string

	for _, arg := range os.Args[1:] {
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			for i := 1; i < len(arg); i++ {
				switch arg[i] {
				case 'n': noConvert = true
				case 'e': escapeHTML = true
				case 'i': indent = true
				case 'k': parseKeys = true
				case 'h': showHelp = true
				case 'v': showVersion = true
				case 'y', 't', 'j', 'c', 'r':
					formatChars += string(arg[i])
				}
			}
		}
	}

	if showHelp {
		printHelp()
		return
	}
	if showVersion {
		fmt.Println("v0.0.0")
		return
	}

	inputFormat, outputFormat := determineFormats(formatChars)

	inputData, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
		os.Exit(1)
	}

	var data interface{}
	switch inputFormat {
	case "j":
		err = json.Unmarshal(inputData, &data)
		if err != nil {
			// Try YAML if JSON fails, but wait, yj says "Error parsing JSON"
			fmt.Fprintf(os.Stderr, "Error parsing JSON: %v\n", err)
			os.Exit(1)
		}
	case "y":
		var node yaml.Node
		err = yaml.Unmarshal(inputData, &node)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing YAML: %v\n", err)
			os.Exit(1)
		}
		if len(node.Content) > 0 {
			err = node.Content[0].Decode(&data)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error decoding YAML: %v\n", err)
				os.Exit(1)
			}
		}
	case "t":
		err = toml.Unmarshal(inputData, &data)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing TOML: %v\n", err)
			os.Exit(1)
		}
	case "c":
		err = hcl.Unmarshal(inputData, &data)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing HCL: %v\n", err)
			os.Exit(1)
		}
	}

	if !noConvert {
		data = convertSpecialFloats(data, true)
	}

	if parseKeys && outputFormat == "y" {
		data = convertKeys(data)
	}

	var output []byte
	switch outputFormat {
	case "j":
		buf := &bytes.Buffer{}
		encoder := json.NewEncoder(buf)
		encoder.SetEscapeHTML(escapeHTML)
		if indent {
			encoder.SetIndent("", "  ")
		}
		err = encoder.Encode(data)
		output = buf.Bytes()
		// Remove the trailing newline that json.Encoder adds if it wasn't there?
		// No, yj seems to add it. Let's check.
	case "y":
		output, err = yaml.Marshal(data)
	case "t":
		buf := &bytes.Buffer{}
		encoder := toml.NewEncoder(buf)
		if indent {
			encoder.Indent = "  "
		}
		err = encoder.Encode(data)
		output = buf.Bytes()
	case "c":
		// HCL output is a bit tricky, but yj seems to use something that
		// produces HCL. Let's try YAML and see if it's close? No.
		// Actually, let's use a simple HCL marshaler or just YAML if it's close.
		// Wait, HCL output was: "b" = 2\n\n"a" = 1
		output, err = marshalHCL(data)
	}

	if err != nil {
		fmt.Fprintf(os.Stderr, "Error marshaling: %v\n", err)
		os.Exit(1)
	}

	os.Stdout.Write(output)
}

func determineFormats(chars string) (string, string) {
	var formats []string
	for _, c := range chars {
		if c == 'r' {
			formats = append(formats, "j", "y")
		} else {
			formats = append(formats, string(c))
		}
	}
	if len(formats) == 0 {
		return "y", "j"
	}
	if len(formats) == 1 {
		return formats[0], "j"
	}
	return formats[len(formats)-2], formats[len(formats)-1]
}

func convertSpecialFloats(v interface{}, toString bool) interface{} {
	rv := reflect.ValueOf(v)
	if !rv.IsValid() {
		return v
	}
	switch rv.Kind() {
	case reflect.Map:
		newMap := reflect.MakeMap(rv.Type()) // This might not preserve order!
		// To preserve order, we should have used a different type.
		// ... (Wait, I'll fix this later)
	}
	// ... (Wait, let's use a simpler way)
	return v
}

func convertKeys(v interface{}) interface{} {
	// ...
	return v
}

func marshalHCL(data interface{}) ([]byte, error) {
	// Simple HCL marshaler for maps
	// ...
	return nil, nil
}

func printHelp() {
    // ...
}
EOF
"}

