				var newNode yaml.Node
				if err := yaml.Unmarshal([]byte(keyNode.Value), &newNode); err == nil && len(newNode.Content) > 0 {
					*keyNode = *newNode.Content[0]
				}
			}
			convertKeys(n.Content[i+1])
		}
	} else {
		for _, child := range n.Content {
