func marshalJSON(n *yaml.Node, indent bool, escapeHTML bool) []byte {
	var buf bytes.Buffer
	writeJSON(&buf, n, indent, 0, escapeHTML)
	if !indent {
		buf.WriteByte('\n')
	}
	return buf.Bytes()
}

func writeJSON(w io.Writer, n *yaml.Node, ind bool, depth int, escape bool) {
	switch n.Kind {
	case yaml.ScalarNode:
		var v interface{}
		n.Decode(&v)
		// For NaN/inf that were not converted to string
		if f, ok := v.(float64); ok {
			if math.IsInf(f, 1) {
				w.Write([]byte("1.7976931348623157e+308"))
				return
			} else if math.IsInf(f, -1) {
				w.Write([]byte("-1.7976931348623157e+308"))
				return
			} else if math.IsNaN(f) {
				w.Write([]byte("null"))
				return
			}
		}
		b, _ := jsonMarshal(v, escape)
		w.Write(b)
	case yaml.SequenceNode:
		w.Write([]byte("["))
		for i, child := range n.Content {
			if i > 0 {
				w.Write([]byte(","))
			}
			if ind {
				w.Write([]byte("\n" + strings.Repeat("  ", depth+1)))
			}
			writeJSON(w, child, ind, depth+1, escape)
		}
		if ind && len(n.Content) > 0 {
			w.Write([]byte("\n" + strings.Repeat("  ", depth)))
		}
		w.Write([]byte("]"))
	case yaml.MappingNode:
		w.Write([]byte("{"))
		for i := 0; i < len(n.Content); i += 2 {
			if i > 0 {
				w.Write([]byte(","))
			}
			if ind {
				w.Write([]byte("\n" + strings.Repeat("  ", depth+1)))
			}
			// JSON keys must be strings
			keyNode := n.Content[i]
			var key interface{}
			keyNode.Decode(&key)
			keyBytes, _ := json.Marshal(fmt.Sprint(key))
			w.Write(keyBytes)
			w.Write([]byte(":"))
			if ind {
				w.Write([]byte(" "))
			}
			writeJSON(w, n.Content[i+1], ind, depth+1, escape)
		}
		if ind && len(n.Content) > 0 {
			w.Write([]byte("\n" + strings.Repeat("  ", depth)))
		}
		w.Write([]byte("}"))
	}
}

func jsonMarshal(v interface{}, escape bool) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(escape)
	err := enc.Encode(v)
	if err != nil {
		return nil, err
	}
	b := buf.Bytes()
	return bytes.TrimSpace(b), nil
}

func marshalHCL(data interface{}) []byte {
	var buf bytes.Buffer
	writeHCL(&buf, data, 0)
	return buf.Bytes()
}

func writeHCL(w io.Writer, data interface{}, depth int) {
	rv := reflect.ValueOf(data)
	if !rv.IsValid() {
		w.Write([]byte("null"))
		return
	}
	switch rv.Kind() {
	case reflect.Map:
		keys := rv.MapKeys()
		// Sort keys to be deterministic if no order is available?
		// Actually, if it's a map[string]interface{}, order is lost.
		// But let's just do it.
		for i, k := range keys {
			if i > 0 {
				w.Write([]byte("\n"))
			}
			fmt.Fprintf(w, "%s%q = ", strings.Repeat("  ", depth), k.Interface())
			writeHCL(w, rv.MapIndex(k).Interface(), depth+1)
			w.Write([]byte("\n"))
		}
	case reflect.Slice:
		w.Write([]byte("["))
		for i := 0; i < rv.Len(); i++ {
			if i > 0 {
				w.Write([]byte(", "))
			}
			writeHCL(w, rv.Index(i).Interface(), depth+1)
		}
		w.Write([]byte("]"))
	default:
		b, _ := json.Marshal(data)
		w.Write(b)
	}
}

func printHelp() {
	fmt.Println(`Usage: yj [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version`)
}
EOF
"}

